from pathlib import Path
import base64
import re
import zlib

# Canonical responsive/input refinement for the V3 Infrastructure Dossier.
# Changes layout and input behavior only; portfolio content is intentionally untouched.
path = Path("index.html")
s = path.read_text(encoding="utf-8")

MARKER = "RESPONSIVE_V4 — adaptive layout + input capability refinement"
if MARKER in s:
    print("Responsive V4 refinement already applied")
    raise SystemExit(0)
if "PORTFOLIO_SYSTEM_V3 — Infrastructure Dossier" not in s:
    raise RuntimeError("V3 portfolio system marker not found; refusing to patch an unknown design generation")

def unpack(payload):
    return zlib.decompress(base64.b64decode(payload)).decode("utf-8")

def replace_block(text, start, end, replacement):
    pattern = re.escape(start) + r".*?" + re.escape(end)
    out, n = re.subn(pattern, lambda _m: replacement, text, count=1, flags=re.S)
    if n != 1:
        raise RuntimeError(f"Expected block not found: {start}")
    return out

portfolio_css = unpack("")
resume_portal_css = unpack("")

s = replace_block(s, "/* PORTFOLIO_SYSTEM_V3 — Infrastructure Dossier */", "/* /PORTFOLIO_SYSTEM_V3 */", portfolio_css)
s = replace_block(s, "/* RESUME_PORTAL_V3 */", "/* /RESUME_PORTAL_V3 */", resume_portal_css)
path.write_text(s, encoding="utf-8")
print("Responsive V4 portfolio refinement applied")
